const state={activeHex:'#9B435C',family:'All',search:'lipstick',selected:null,compare:[],scanStream:null,skinStream:null,skinShades:[],skinType:'Lipstick',skinActiveShade:null,skinPhotoReady:false,skinStrokes:[],skinDrawing:null,skinBrush:36,skinOpacity:.72,tryProduct:null,profile:{preferredFamilies:['Rose','Berry'],preferredFinishes:['Matte','Satin'],purchases:['VL-RW01','TG-DM07']}};
const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
function hexToRgb(hex){const value=hex.replace('#','');return{r:parseInt(value.slice(0,2),16),g:parseInt(value.slice(2,4),16),b:parseInt(value.slice(4,6),16)}}
function rgbToHex(r,g,b){return '#'+[r,g,b].map(value=>clamp(Math.round(value),0,255).toString(16).padStart(2,'0')).join('').toUpperCase()}
function rgbToLab(r,g,b){let [R,G,B]=[r,g,b].map(v=>{v/=255;return v>.04045?((v+.055)/1.055)**2.4:v/12.92});let x=(R*.4124+G*.3576+B*.1805)/.95047,y=(R*.2126+G*.7152+B*.0722),z=(R*.0193+G*.1192+B*.9505)/1.08883;[x,y,z]=[x,y,z].map(v=>v>.008856?Math.cbrt(v):7.787*v+16/116);return{L:116*y-16,a:500*(x-y),b:200*(y-z)}}
function hexToLab(hex){const c=hexToRgb(hex);return rgbToLab(c.r,c.g,c.b)}
function distance(a,b){const p=hexToLab(a),q=hexToLab(b);return Math.hypot(p.L-q.L,p.a-q.a,p.b-q.b)}
function matchScore(hex){return Math.round(clamp(100-distance(state.activeHex,hex)*2,62,99))}
function closest(limit=products.length){return products.slice().sort((a,b)=>distance(state.activeHex,a.hex)-distance(state.activeHex,b.hex)).slice(0,limit)}
function similarProducts(product,limit=3,excluded=[]){if(!product)return[];return products.filter(p=>p.id!==product.id&&!excluded.includes(p.id)).sort((a,b)=>distance(product.hex,a.hex)-distance(product.hex,b.hex)).slice(0,limit)}
function updateModalProductReference(prefix,product){if(!product)return;const image=$(`#${prefix}ProductImage`);image.src='assets/lip-products.png';image.style.objectPosition=product.pos;image.alt=`${product.brand} ${product.shade}`;$(`#${prefix}ProductName`).textContent=`${product.brand} · ${product.name}`;$(`#${prefix}ProductShade`).textContent=`${product.shade} · ${product.hex}`}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function productCard(product,compact=false){return `<article class="product-card" data-product="${product.id}"><div class="product-image" style="--pos:${product.pos}"><img src="assets/lip-products.png" alt="${product.brand} ${product.shade} lip colour"><span class="match">${matchScore(product.hex)}% shade match</span>${product.verified?'<span class="verified">✓ Reference checked</span>':''}</div><div class="product-body"><span class="product-brand">${product.brand}</span><h3>${product.name}</h3><div class="product-shade"><i style="--shade:${product.hex}"></i><span>${product.shade} · ${product.hex}</span></div><div class="product-price">₹${product.price}<del>₹${product.mrp}</del></div><div class="product-rating"><b>${product.rating} ★</b><span>${product.reviews.toLocaleString('en-IN')} Reviews</span></div>${compact?'':`<div class="card-actions"><button type="button" data-try="${product.id}">Try this shade</button><button class="compare-toggle ${state.compare.includes(product.id)?'is-active':''}" type="button" data-compare="${product.id}" aria-label="Add ${product.shade} to comparison">${state.compare.includes(product.id)?'✓':'＋'}</button></div>`}</div></article>`}
function currentFilters(){return{types:$$('input[name=type]:checked').map(x=>x.value),finishes:$$('input[name=finish]:checked').map(x=>x.value),rating:$('#ratingFour').checked,verified:$('#verifiedOnly').checked}}
function filteredProducts(){const f=currentFilters(),query=state.search.trim().toLowerCase();let list=products.filter(p=>f.types.includes(p.type)&&(!f.finishes.length||f.finishes.includes(p.finish))&&(!f.rating||p.rating>=4)&&(!f.verified||p.verified)&&(state.family==='All'||p.family===state.family)&&(!query||`${p.brand} ${p.name} ${p.shade} ${p.hex} ${p.family}`.toLowerCase().includes(query)||query==='lipstick'));const sort=$('#sortSelect').value;if(sort==='match')list.sort((a,b)=>distance(state.activeHex,a.hex)-distance(state.activeHex,b.hex));if(sort==='rating')list.sort((a,b)=>b.rating-a.rating);if(sort==='priceLow')list.sort((a,b)=>a.price-b.price);if(sort==='priceHigh')list.sort((a,b)=>b.price-a.price);return list}
function renderProducts(){const list=filteredProducts();$('#productGrid').innerHTML=list.map(product=>productCard(product)).join('');$('#resultCount').textContent=list.length;$('#emptyState').hidden=!!list.length;wireProductCards($('#productGrid'))}
function wireProductCards(root){$$('[data-product]',root).forEach(card=>card.addEventListener('click',event=>{if(event.target.closest('[data-try],[data-compare]'))return;openProduct(card.dataset.product)}));$$('[data-try]',root).forEach(button=>button.addEventListener('click',()=>openFace(products.find(p=>p.id===button.dataset.try))));$$('[data-compare]',root).forEach(button=>button.addEventListener('click',()=>toggleCompare(button.dataset.compare)))}
function toggleCompare(id){const index=state.compare.indexOf(id);if(index>=0)state.compare.splice(index,1);else if(state.compare.length<4)state.compare.push(id);else return toast('You can compare up to four shades.');renderCompare();renderProducts()}
function addToCompare(id){if(state.compare.includes(id))return toast('This shade is already in your comparison.');if(state.compare.length>=4)return toast('You can compare up to four shades.');state.compare.push(id);renderCompare();renderProducts();toast('Shade added to comparison.')}
function renderDetailCompareSuggestions(product){const holder=$('#detailCompareSuggestions');if(!holder||!product)return;const suggestions=similarProducts(product,3);holder.innerHTML=suggestions.map(p=>{const added=state.compare.includes(p.id);return `<button type="button" class="comparison-suggestion ${added?'is-added':''}" data-suggest-compare="${p.id}" ${added?'disabled':''}><img src="assets/lip-products.png" style="object-position:${p.pos}" alt="${p.brand} ${p.shade}"><span><b>${p.shade}</b><small>${p.brand} · ${p.hex}</small></span><em>${added?'Added':'+ Add'}</em></button>`}).join('');$$('[data-suggest-compare]',holder).forEach(button=>button.addEventListener('click',()=>addToCompare(button.dataset.suggestCompare)))}
function renderCompare(){const selected=state.compare.map(id=>products.find(p=>p.id===id)).filter(Boolean);$('#compareDock').hidden=!selected.length;$('#compareNames').textContent=selected.map(p=>p.shade).join(' · ');$('#compareChips').innerHTML=selected.map(p=>`<i style="--c:${p.hex}" title="${p.shade}"></i>`).join('');const detailButton=$('#detailAddCompare');if(detailButton){const added=!!state.selected&&state.compare.includes(state.selected.id);detailButton.textContent=added?'✓ Added to comparison':'Add to comparison';detailButton.classList.toggle('is-added',added);detailButton.disabled=added}if(state.selected)renderDetailCompareSuggestions(state.selected)}
function setReference(hex){state.activeHex=hex.toUpperCase();$('#activeColourChip').style.background=state.activeHex;$('#activeColourText').textContent=state.activeHex;$('#bannerHex').textContent=state.activeHex;renderProducts();renderScanMatches();if($('#skinPalette'))renderSkinControls()}
function openProduct(id){const p=products.find(item=>item.id===id);if(!p)return;state.selected=p;$('#listingView').hidden=true;$('#productView').hidden=false;$('#detailBrand').textContent=p.brand;$('#detailName').textContent=p.name;$('#detailShade').textContent=p.shade;$('#detailHex').textContent=p.hex;$('#detailSwatch').style.setProperty('--detail',p.hex);$('#detailPrice').textContent=`₹${p.price}`;$('#detailMrp').textContent=`₹${p.mrp}`;$('#detailRating').textContent=`${p.rating} ★`;$('#detailReviews').textContent=`${p.reviews.toLocaleString('en-IN')} Ratings, ${Math.round(p.reviews*.18).toLocaleString('en-IN')} Reviews`;$('#detailMatch').textContent=`${matchScore(p.hex)}% shade match`;$('#detailSpecs').innerHTML=`<div><span>Product type</span><b>${p.type}</b></div><div><span>Finish</span><b>${p.finish}</b></div><div><span>Shade family</span><b>${p.family}</b></div><div><span>Net quantity</span><b>1 unit</b></div>`;const rgb=hexToRgb(p.hex),lab=hexToLab(p.hex);$('#passportSwatch').style.setProperty('--passport',p.hex);$('#passportHex').textContent=p.hex;$('#passportRgb').textContent=`${rgb.r}, ${rgb.g}, ${rgb.b}`;$('#passportLab').textContent=`${Math.round(lab.L)}, ${Math.round(lab.a)}, ${Math.round(lab.b)}`;$('#passportFinish').textContent=p.finish;$('#detailShadeOptions').innerHTML=closest(8).map(x=>`<button type="button" class="${x.id===p.id?'is-active':''}" style="--shade:${x.hex}" data-detail-shade="${x.id}" aria-label="View ${x.shade}"></button>`).join('');$$('[data-detail-shade]').forEach(button=>button.addEventListener('click',()=>openProduct(button.dataset.detailShade)));const similar=products.filter(x=>x.id!==p.id).sort((a,b)=>distance(p.hex,a.hex)-distance(p.hex,b.hex)).slice(0,5);$('#similarGrid').innerHTML=similar.map(x=>productCard(x,true)).join('');wireProductCards($('#similarGrid'));renderCompare();window.scrollTo({top:0,behavior:'smooth'})}
function showListing(){stopAllCameras();$('#productView').hidden=true;$('#listingView').hidden=false;window.scrollTo({top:0,behavior:'smooth'})}
function openDialog(id){const dialog=$(`#${id}`);if(dialog&&!dialog.open)dialog.showModal()}
function closeDialog(dialog){if(dialog?.open)dialog.close()}

// Precise camera and image colour picker
const scan={stage:$('#scanStage'),video:$('#scanVideo'),canvas:$('#scanCanvas'),empty:$('#scanEmpty'),marker:$('#scanMarker'),loupe:$('#scanLoupe'),button:$('#scanCamera'),status:$('#scanStatus')};
function stopScan(){if(state.scanStream){state.scanStream.getTracks().forEach(track=>track.stop());state.scanStream=null}scan.video.srcObject=null}
async function startScan(){stopScan();try{state.scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});scan.video.srcObject=state.scanStream;await scan.video.play();scan.stage.className='camera-stage has-video';scan.button.textContent='Capture frame';scan.button.dataset.mode='capture';scan.status.textContent='Live · frame the colour, then capture'}catch(error){toast(error?.name==='NotAllowedError'?'Camera permission was not granted.':'Camera is unavailable. Upload a photo instead.')};}
function captureScan(){if(!scan.video.videoWidth)return;scan.canvas.width=scan.video.videoWidth;scan.canvas.height=scan.video.videoHeight;scan.canvas.getContext('2d',{willReadFrequently:true}).drawImage(scan.video,0,0);stopScan();scan.stage.className='camera-stage has-image';scan.button.textContent='Retake';scan.button.dataset.mode='retake';scan.status.textContent='Frame frozen · tap any visible pixel';scan.marker.hidden=true;scan.loupe.hidden=true}
function loadScanFile(file){if(!file)return;const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{const scale=Math.min(1,1920/Math.max(image.naturalWidth,image.naturalHeight));scan.canvas.width=Math.round(image.naturalWidth*scale);scan.canvas.height=Math.round(image.naturalHeight*scale);scan.canvas.getContext('2d',{willReadFrequently:true}).drawImage(image,0,0,scan.canvas.width,scan.canvas.height);URL.revokeObjectURL(url);scan.stage.className='camera-stage has-image';scan.button.textContent='Start camera';scan.button.dataset.mode='';scan.status.textContent='Photo ready · tap any visible pixel';scan.marker.hidden=true;scan.loupe.hidden=true};image.src=url}
function canvasPoint(event,canvas){const rect=canvas.getBoundingClientRect(),ratio=canvas.width/canvas.height,box=rect.width/rect.height;let width,height,offX=0,offY=0;if(ratio>box){width=rect.width;height=width/ratio;offY=(rect.height-height)/2}else{height=rect.height;width=height*ratio;offX=(rect.width-width)/2}const px=event.clientX-rect.left-offX,py=event.clientY-rect.top-offY;if(px<0||py<0||px>width||py>height)return null;return{x:px/width*canvas.width,y:py/height*canvas.height,screenX:event.clientX-scan.stage.getBoundingClientRect().left,screenY:event.clientY-scan.stage.getBoundingClientRect().top}}
function median(values){const sorted=values.slice().sort((a,b)=>a-b);return sorted[Math.floor(sorted.length/2)]}
function samplePixel(ctx,x,y){x=clamp(Math.round(x),0,ctx.canvas.width-1);y=clamp(Math.round(y),0,ctx.canvas.height-1);const centre=ctx.getImageData(x,y,1,1).data;if(centre[3]<200)return{transparent:true,x,y};const centreLab=rgbToLab(centre[0],centre[1],centre[2]),sx=Math.max(0,x-2),sy=Math.max(0,y-2),ex=Math.min(ctx.canvas.width-1,x+2),ey=Math.min(ctx.canvas.height-1,y+2),data=ctx.getImageData(sx,sy,ex-sx+1,ey-sy+1).data,samples=[];for(let i=0;i<data.length;i+=4){if(data[i+3]<200)continue;const lab=rgbToLab(data[i],data[i+1],data[i+2]);if(Math.hypot(lab.L-centreLab.L,lab.a-centreLab.a,lab.b-centreLab.b)<=14)samples.push([data[i],data[i+1],data[i+2]])}return{x,y,centre:rgbToHex(centre[0],centre[1],centre[2]),hex:rgbToHex(median(samples.map(c=>c[0])),median(samples.map(c=>c[1])),median(samples.map(c=>c[2])))} }
function drawLoupe(result,point){const ctx=scan.loupe.getContext('2d'),size=13,sx=clamp(result.x-6,0,scan.canvas.width-size),sy=clamp(result.y-6,0,scan.canvas.height-size);ctx.clearRect(0,0,96,96);ctx.imageSmoothingEnabled=false;ctx.drawImage(scan.canvas,sx,sy,size,size,0,0,96,96);ctx.strokeStyle='#fff';ctx.beginPath();ctx.moveTo(48,0);ctx.lineTo(48,96);ctx.moveTo(0,48);ctx.lineTo(96,48);ctx.stroke();scan.marker.style.left=`${point.screenX}px`;scan.marker.style.top=`${point.screenY}px`;scan.marker.hidden=false;scan.loupe.style.left=`${clamp(point.screenX+24,8,scan.stage.clientWidth-98)}px`;scan.loupe.style.top=`${clamp(point.screenY>120?point.screenY-108:point.screenY+24,8,scan.stage.clientHeight-98)}px`;scan.loupe.hidden=false}
function updateScan(hex,quality){const rgb=hexToRgb(hex);$('#scanColour').style.setProperty('--scan',hex);$('#scanHex').textContent=hex;$('#scanRgb').textContent=`RGB ${rgb.r}, ${rgb.g}, ${rgb.b}`;$('#scanQuality').textContent=quality;setReference(hex)}
function renderScanMatches(){if(!$('#scanMatches'))return;$('#scanMatches').innerHTML=closest(4).map(p=>`<div class="scan-match"><i style="--c:${p.hex}"></i><span><b>${p.shade}</b><small>${p.brand} · ${p.hex}</small></span><b>${matchScore(p.hex)}%</b></div>`).join('')}

// Face try-on
const tryOn=new window.ShadeTryOn({video:$('#tryOnVideo'),canvas:$('#tryOnCanvas'),stage:$('#tryOnStage'),onStatus:(kind,message)=>{$('#tryOnStatus').textContent=message;$('#tryOnHint').textContent=kind==='live'?'Find your face':message;$('#tryOnStage').classList.toggle('searching',kind!=='live')}});
function renderTrySuggestions(product){const holder=$('#trySuggestions');if(!holder||!product)return;holder.innerHTML=similarProducts(product,3).map(p=>`<button type="button" data-try-suggest="${p.id}"><img src="assets/lip-products.png" style="object-position:${p.pos}" alt="${p.brand} ${p.shade}"><span><b>${p.shade}</b><small>${p.hex}</small></span></button>`).join('');$$('[data-try-suggest]',holder).forEach(button=>button.addEventListener('click',()=>{const next=products.find(p=>p.id===button.dataset.trySuggest);buildTryOn(next);state.tryProduct=next;updateModalProductReference('try',next);renderTrySuggestions(next)}))}
function setTryColour(region,hex,button){tryOn.set(region,{hex});const holder=button.parentElement;$$('button',holder).forEach(x=>x.classList.toggle('is-active',x===button));if(region==='lips'){const product=products.find(p=>p.hex===hex)||products.slice().sort((a,b)=>distance(hex,a.hex)-distance(hex,b.hex))[0];state.tryProduct=product;updateModalProductReference('try',product);renderTrySuggestions(product)}}
function buildTryOn(product){const values=[product?.hex,state.activeHex,...products.map(p=>p.hex)].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).slice(0,10),brows=['#2C1B18','#4A3029','#68463A','#7A5848','#936E5A'],eyes=['#8A5D70','#9C7566','#75516C','#A97862','#6E587F','#A48B70'];[["#tryLipSwatches",values,'lips'],['#tryBrowSwatches',brows,'brows'],['#tryEyeSwatches',eyes,'eyes']].forEach(([selector,colours,region])=>{const holder=$(selector);holder.innerHTML=colours.map((hex,index)=>`<button type="button" class="${index===0?'is-active':''}" style="--swatch:${hex}" data-colour="${hex}" aria-label="Use ${hex}"></button>`).join('');tryOn.set(region,{hex:colours[0]});$$('button',holder).forEach(button=>button.addEventListener('click',()=>setTryColour(region,button.dataset.colour,button)))})}
function openFace(product){const chosen=product||state.selected||closest(1)[0];state.tryProduct=chosen;buildTryOn(chosen);updateModalProductReference('try',chosen);renderTrySuggestions(chosen);openDialog('tryOnDialog')}

// Capture-first hand and skin shade painting
const skin={stage:$('#skinStage'),video:$('#skinVideo'),base:$('#skinBaseCanvas'),paint:$('#skinCanvas'),button:$('#skinStart'),status:$('#skinCaptureStatus')};
function stopSkin(){if(state.skinStream){state.skinStream.getTracks().forEach(track=>track.stop());state.skinStream=null}skin.video.srcObject=null;if(skin.stage.classList.contains('has-video')){skin.stage.className='skin-stage';skin.button.textContent='Start camera';skin.button.dataset.mode='';skin.status.textContent='Camera stopped · capture or upload a photo'}}
function seedSkin(product){const base=product||state.selected||closest(1)[0];const nearby=products.filter(p=>p.id!==base.id).sort((a,b)=>distance(base.hex,a.hex)-distance(base.hex,b.hex)).slice(0,2);state.skinShades=[base.id,...nearby.map(p=>p.id)].slice(0,4);state.skinActiveShade=state.skinShades[0]||null;state.skinStrokes=[];renderSkinControls();renderSkinPaint()}
function openSkin(product){if(product)seedSkin(product);else if(state.compare.length){state.skinShades=state.compare.slice(0,4);state.skinActiveShade=state.skinShades[0]||null;state.skinStrokes=[]}else if(!state.skinShades.length)seedSkin(closest(1)[0]);renderSkinControls();renderSkinPaint();openDialog('skinDialog')}
function skinRemark(product){const savedDistance=distance(state.activeHex,product.hex),history=state.profile.purchases.map(id=>products.find(p=>p.id===id)).filter(Boolean).map(p=>({product:p,gap:distance(p.hex,product.hex)})).sort((a,b)=>a.gap-b.gap)[0];if(savedDistance<=7)return{label:'Perfect match',detail:`near your saved ${state.activeHex}`,tone:'perfect'};if(history&&history.gap<=10)return{label:'Close match',detail:`similar to ${history.product.shade} you bought`,tone:'close'};if(state.profile.preferredFamilies.includes(product.family)&&state.profile.preferredFinishes.includes(product.finish))return{label:'Good fit',detail:`matches your ${product.family.toLowerCase()} and ${product.finish.toLowerCase()} preferences`,tone:'good'};if(savedDistance<=22)return{label:'Worth trying',detail:'close to your saved colour range',tone:'good'};return{label:'New direction',detail:'outside your usual saved range',tone:'new'} }
function skinProductList(){if(state.skinType==='Brow')return products.filter(p=>p.type==='Brow').concat(products.filter(p=>p.family==='Brown'));if(state.skinType==='Tint')return products.filter(p=>p.type==='Tint').concat(products.filter(p=>p.type==='Lipstick'));return products.filter(p=>p.type==='Lipstick'||state.skinType==='Eyeshadow')}
function renderSkinSuggestions(product){const holder=$('#skinSuggestions');if(!holder||!product)return;const suggestions=similarProducts(product,3,state.skinShades);holder.innerHTML=suggestions.length?suggestions.map(p=>`<button type="button" data-skin-suggest="${p.id}"><img src="assets/lip-products.png" style="object-position:${p.pos}" alt="${p.brand} ${p.shade}"><span><b>${p.shade}</b><small>${p.hex}</small></span><em>+ Add</em></button>`).join(''):'<span class="privacy-copy">Remove a shade to see another close option.</span>';$$('[data-skin-suggest]',holder).forEach(button=>button.addEventListener('click',()=>{if(state.skinShades.length>=4)return toast('You can compare up to four shades.');state.skinShades.push(button.dataset.skinSuggest);state.skinActiveShade=button.dataset.skinSuggest;renderSkinControls();updateSkinPaintStatus()}))}
function renderSkinControls(){const list=skinProductList();$('#skinPalette').innerHTML=list.slice(0,12).map(p=>`<button type="button" class="${state.skinShades.includes(p.id)?'is-active':''} ${state.skinActiveShade===p.id?'is-current':''}" data-skin-shade="${p.id}"><i style="--c:${p.hex}"></i><span><b>${p.shade}</b><small>${p.hex}</small></span></button>`).join('');$$('[data-skin-shade]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.skinShade;if(!state.skinShades.includes(id)){if(state.skinShades.length>=4)return toast('You can paint up to four shades. Remove one first.');state.skinShades.push(id)}state.skinActiveShade=id;renderSkinControls();updateSkinPaintStatus()}));const chosen=state.skinShades.map(id=>products.find(p=>p.id===id)).filter(Boolean);if(!state.skinActiveShade||!state.skinShades.includes(state.skinActiveShade))state.skinActiveShade=chosen[0]?.id||null;$('#skinComparison').innerHTML=chosen.map(p=>{const remark=skinRemark(p);return `<div class="skin-choice ${state.skinActiveShade===p.id?'is-current':''}"><button type="button" class="skin-choice-main" data-skin-select="${p.id}"><i style="--c:${p.hex}"></i><span><b>${p.shade}</b><small class="fit-${remark.tone}">${remark.label} · ${remark.detail}</small></span><code>${p.hex}</code></button><button type="button" class="skin-remove" data-skin-remove="${p.id}" aria-label="Remove ${p.shade}">×</button></div>`}).join('')||'<p class="privacy-copy">Choose at least one shade.</p>';$$('[data-skin-select]').forEach(button=>button.addEventListener('click',()=>{state.skinActiveShade=button.dataset.skinSelect;renderSkinControls();updateSkinPaintStatus()}));$$('[data-skin-remove]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.skinRemove;state.skinShades=state.skinShades.filter(value=>value!==id);state.skinStrokes=state.skinStrokes.filter(stroke=>stroke.shadeId!==id);if(state.skinActiveShade===id)state.skinActiveShade=state.skinShades[0]||null;renderSkinControls();renderSkinPaint()}));const active=products.find(p=>p.id===state.skinActiveShade)||chosen[0];if(active){updateModalProductReference('skin',active);renderSkinSuggestions(active)}$('#skinPreferenceText').textContent=`Saved colour ${state.activeHex} · ${state.profile.preferredFinishes.join('/').toLowerCase()} preference · past purchase: ${products.find(p=>p.id===state.profile.purchases[0])?.shade||'none'}`}
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
function updateSkinPaintStatus(){const active=products.find(p=>p.id===state.skinActiveShade),applied=new Set(state.skinStrokes.map(stroke=>stroke.shadeId)).size;if(!state.skinPhotoReady){$('#skinPaintStatus').textContent='Capture or upload a photo before painting.';return}$('#skinPaintStatus').textContent=active?`${applied} of 4 shades applied · painting ${active.shade} ${active.hex}. Click or drag on the photo.`:'Choose a shade before painting.'}
function drawSkinStroke(ctx,stroke,product){const formulaFactor=stroke.type==='Tint'?.72:stroke.type==='Eyeshadow'?.62:stroke.type==='Brow'?.82:1,alpha=state.skinOpacity*formulaFactor;ctx.save();ctx.globalCompositeOperation='multiply';ctx.globalAlpha=alpha;ctx.strokeStyle=product.hex;ctx.fillStyle=product.hex;ctx.lineWidth=stroke.size;ctx.lineCap='round';ctx.lineJoin='round';ctx.shadowColor=product.hex;ctx.shadowBlur=stroke.size*.18;if(stroke.points.length===1){ctx.beginPath();ctx.arc(stroke.points[0].x,stroke.points[0].y,stroke.size/2,0,Math.PI*2);ctx.fill()}else{ctx.beginPath();ctx.moveTo(stroke.points[0].x,stroke.points[0].y);stroke.points.slice(1).forEach(point=>ctx.lineTo(point.x,point.y));ctx.stroke()}ctx.restore()}
function drawSkinLabel(ctx,stroke,product){const point=stroke.points[stroke.points.length-1],fontSize=Math.max(22,Math.round(ctx.canvas.width*.027)),pad=Math.round(fontSize*.55),square=Math.round(fontSize*.9);ctx.save();ctx.font=`700 ${fontSize}px Arial`;const textWidth=ctx.measureText(product.hex).width,labelWidth=textWidth+square+pad*3,labelHeight=fontSize+pad*1.5;let x=point.x+stroke.size*.62+8;if(x+labelWidth>ctx.canvas.width-8)x=point.x-stroke.size*.62-labelWidth-8;let y=clamp(point.y-labelHeight/2,8,ctx.canvas.height-labelHeight-8);x=clamp(x,8,ctx.canvas.width-labelWidth-8);ctx.fillStyle='rgba(255,255,255,.94)';ctx.strokeStyle=product.hex;ctx.lineWidth=Math.max(2,fontSize*.12);roundRect(ctx,x,y,labelWidth,labelHeight,Math.max(6,fontSize*.4));ctx.fill();ctx.stroke();ctx.fillStyle=product.hex;roundRect(ctx,x+pad,y+(labelHeight-square)/2,square,square,3);ctx.fill();ctx.fillStyle='#2d1527';ctx.textBaseline='middle';ctx.fillText(product.hex,x+pad*2+square,y+labelHeight/2+1);ctx.restore()}
function renderSkinPaint(){const canvas=skin.paint,ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);state.skinStrokes.forEach(stroke=>{const product=products.find(p=>p.id===stroke.shadeId);if(product)drawSkinStroke(ctx,stroke,product)});state.skinShades.forEach(id=>{const product=products.find(p=>p.id===id),stroke=[...state.skinStrokes].reverse().find(item=>item.shadeId===id);if(product&&stroke)drawSkinLabel(ctx,stroke,product)});updateSkinPaintStatus()}
function prepareSkinPhoto(width,height){const scale=Math.min(1,1920/Math.max(width,height)),w=Math.round(width*scale),h=Math.round(height*scale);[skin.base,skin.paint].forEach(canvas=>{canvas.width=w;canvas.height=h});state.skinPhotoReady=true;state.skinStrokes=[];state.skinDrawing=null;skin.stage.className='skin-stage has-photo';skin.button.textContent='Retake';skin.button.dataset.mode='retake';skin.status.textContent='Photo ready · choose a shade and paint';renderSkinPaint();return{width:w,height:h}}
async function startSkin(){if(skin.button.dataset.mode==='capture')return captureSkinPhoto();stopSkin();try{state.skinStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});skin.video.srcObject=state.skinStream;await skin.video.play();state.skinPhotoReady=false;state.skinStrokes=[];skin.stage.className='skin-stage has-video';skin.button.textContent='Capture photo';skin.button.dataset.mode='capture';skin.status.textContent='Camera live · frame your hand or skin, then capture';updateSkinPaintStatus()}catch(error){stopSkin();toast(error?.name==='NotAllowedError'?'Camera permission was not granted.':'Camera is unavailable. Upload a photo instead.')};}
function captureSkinPhoto(){if(!skin.video.videoWidth)return;const size=prepareSkinPhoto(skin.video.videoWidth,skin.video.videoHeight);skin.base.getContext('2d').drawImage(skin.video,0,0,size.width,size.height);stopSkin();skin.stage.className='skin-stage has-photo';skin.status.textContent='Photo captured · choose a shade and paint';renderSkinPaint()}
function loadSkinPhoto(file){if(!file)return;stopSkin();const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{const size=prepareSkinPhoto(image.naturalWidth,image.naturalHeight);skin.base.getContext('2d').drawImage(image,0,0,size.width,size.height);URL.revokeObjectURL(url);skin.status.textContent='Photo uploaded · choose a shade and paint';renderSkinPaint()};image.src=url}
function resetSkinPhoto(){stopSkin();state.skinPhotoReady=false;state.skinStrokes=[];state.skinDrawing=null;skin.stage.className='skin-stage';skin.button.textContent='Start camera';skin.button.dataset.mode='';skin.status.textContent='Waiting for a photo';skin.base.getContext('2d').clearRect(0,0,skin.base.width,skin.base.height);skin.paint.getContext('2d').clearRect(0,0,skin.paint.width,skin.paint.height);updateSkinPaintStatus()}
function skinCanvasPoint(event){const rect=skin.paint.getBoundingClientRect(),ratio=skin.paint.width/skin.paint.height,box=rect.width/rect.height;let width,height,offX=0,offY=0;if(ratio>box){width=rect.width;height=width/ratio;offY=(rect.height-height)/2}else{height=rect.height;width=height*ratio;offX=(rect.width-width)/2}const x=event.clientX-rect.left-offX,y=event.clientY-rect.top-offY;if(x<0||y<0||x>width||y>height)return null;return{x:x/width*skin.paint.width,y:y/height*skin.paint.height,scale:skin.paint.width/width}}
function beginSkinStroke(event){if(!state.skinPhotoReady)return toast('Capture or upload a photo first.');if(!state.skinActiveShade)return toast('Choose a shade first.');const point=skinCanvasPoint(event);if(!point)return;event.preventDefault();skin.paint.setPointerCapture?.(event.pointerId);state.skinDrawing={shadeId:state.skinActiveShade,type:state.skinType,size:state.skinBrush*point.scale,points:[{x:point.x,y:point.y}],pointerId:event.pointerId};state.skinStrokes.push(state.skinDrawing);renderSkinPaint()}
function continueSkinStroke(event){const stroke=state.skinDrawing;if(!stroke||stroke.pointerId!==event.pointerId)return;const point=skinCanvasPoint(event);if(!point)return;event.preventDefault();const last=stroke.points[stroke.points.length-1];if(Math.hypot(point.x-last.x,point.y-last.y)>Math.max(2,stroke.size*.08)){stroke.points.push({x:point.x,y:point.y});renderSkinPaint()}}
function endSkinStroke(event){if(!state.skinDrawing||state.skinDrawing.pointerId!==event.pointerId)return;state.skinDrawing=null;skin.paint.releasePointerCapture?.(event.pointerId);renderSkinPaint()}
function stopAllCameras(){stopScan();tryOn.stop();stopSkin()}

