$('#searchInput').addEventListener('input',event=>{state.search=event.target.value;renderProducts()});$('#clearSearch').addEventListener('click',()=>{$('#searchInput').value='';state.search='';renderProducts()});$('#sortSelect').addEventListener('change',renderProducts);$$('.filters input').forEach(input=>input.addEventListener('change',renderProducts));$$('#familyFilters button').forEach(button=>button.addEventListener('click',()=>{state.family=button.dataset.family;$$('#familyFilters button').forEach(x=>x.classList.toggle('is-active',x===button));renderProducts()}));$('#resetFilters').addEventListener('click',()=>{$$('.filters input[type=checkbox]').forEach(x=>x.checked=x.name==='type');state.family='All';$$('#familyFilters button').forEach(x=>x.classList.toggle('is-active',x.dataset.family==='All'));renderProducts()});
scan.button.addEventListener('click',()=>scan.button.dataset.mode==='capture'?captureScan():startScan());$('#scanUpload').addEventListener('click',()=>$('#scanInput').click());$('#scanInput').addEventListener('change',event=>loadScanFile(event.target.files[0]));scan.canvas.addEventListener('pointerdown',event=>{if(!scan.stage.classList.contains('has-image'))return;const point=canvasPoint(event,scan.canvas);if(!point)return;const result=samplePixel(scan.canvas.getContext('2d',{willReadFrequently:true}),point.x,point.y);scan.marker.style.left=`${point.screenX}px`;scan.marker.style.top=`${point.screenY}px`;scan.marker.hidden=false;if(result.transparent){scan.loupe.hidden=true;$('#scanQuality').textContent='That point is transparent. Tap a visible product or swatch.';return}drawLoupe(result,point);updateScan(result.hex,`Pixel ${result.x}, ${result.y} · centre ${result.centre} · 5 × 5 median ${result.hex}`)});$('#applyScan').addEventListener('click',()=>{closeDialog($('#scanDialog'));$('#sortSelect').value='match';renderProducts();showListing()});
$('#startTryOn').addEventListener('click',()=>tryOn.start());$('#stopTryOn').addEventListener('click',()=>tryOn.stop());$('#tryLipsOn').addEventListener('change',event=>tryOn.set('lips',{on:event.target.checked}));$('#tryBrowsOn').addEventListener('change',event=>tryOn.set('brows',{on:event.target.checked}));$('#tryEyesOn').addEventListener('change',event=>tryOn.set('eyes',{on:event.target.checked}));[['#tryLipIntensity','lips','tryLip'],['#tryBrowIntensity','brows','tryBrow'],['#tryEyeIntensity','eyes','tryEye']].forEach(([selector,region,prefix])=>$(selector).addEventListener('input',event=>{const value=Number(event.target.value);tryOn.set(region,{intensity:value/100});$(`#${prefix}Opacity`).value=`${value}%`;$(`#${prefix}Transparency`).textContent=`Transparency ${100-value}%`}));$$('#tryLipFinish button').forEach(button=>button.addEventListener('click',()=>{$$('#tryLipFinish button').forEach(x=>x.classList.toggle('is-active',x===button));tryOn.set('lips',{finish:button.dataset.finish})}));$$('#tryEyeFinish button').forEach(button=>button.addEventListener('click',()=>{$$('#tryEyeFinish button').forEach(x=>x.classList.toggle('is-active',x===button));tryOn.set('eyes',{finish:button.dataset.finish})}));$('#faceToSkin').addEventListener('click',()=>{tryOn.stop();closeDialog($('#tryOnDialog'));openSkin(state.tryProduct||state.selected)});
$('#skinStart').addEventListener('click',startSkin);$('#skinStop').addEventListener('click',resetSkinPhoto);$('#skinUpload').addEventListener('click',()=>$('#skinInput').click());$('#skinInput').addEventListener('change',event=>{loadSkinPhoto(event.target.files[0]);event.target.value=''});$('#skinType').addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;state.skinType=button.dataset.type;$$('#skinType button').forEach(x=>x.classList.toggle('is-active',x===button));renderSkinControls();updateSkinPaintStatus()});$('#skinBrush').addEventListener('input',event=>{state.skinBrush=Number(event.target.value);$('#skinBrushValue').value=`${state.skinBrush} px`});$('#skinOpacity').addEventListener('input',event=>{const value=Number(event.target.value);state.skinOpacity=value/100;$('#skinOpacityValue').value=`${value}%`;$('#skinTransparencyValue').textContent=`Transparency ${100-value}%`;renderSkinPaint()});$('#skinUndo').addEventListener('click',()=>{state.skinStrokes.pop();renderSkinPaint()});$('#skinClearPaint').addEventListener('click',()=>{state.skinStrokes=[];renderSkinPaint()});skin.paint.addEventListener('pointerdown',beginSkinStroke);skin.paint.addEventListener('pointermove',continueSkinStroke);skin.paint.addEventListener('pointerup',endSkinStroke);skin.paint.addEventListener('pointercancel',endSkinStroke);
document.addEventListener('click',event=>{if(event.target.closest('.purchase-row button'))toast('Added to the demo shopping flow.');if(event.target.closest('.seller-card button'))toast('Seller profile opened in the demo.');if(event.target.closest('.creator-image button'))toast('Creator proof video is represented by the linked demo card.')});window.addEventListener('pagehide',stopAllCameras);
function registerTools(){if(!document.modelContext?.registerTool)return;const register=config=>{try{document.modelContext.registerTool(config)}catch{}};register({name:'get_current_shade_results',description:'Read the active colour reference and closest visible products.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute(){return{reference:state.activeHex,products:closest(5).map(p=>({brand:p.brand,shade:p.shade,hex:p.hex,price:p.price}))}}});register({name:'set_colour_reference',description:'Set a six-digit HEX colour and rerank shade results.',inputSchema:{type:'object',properties:{hex:{type:'string',pattern:'^#?[0-9A-Fa-f]{6}$'}},required:['hex'],additionalProperties:false},execute({hex}){if(!/^#?[0-9A-Fa-f]{6}$/.test(hex))throw new Error('Enter a six-digit HEX colour.');setReference('#'+hex.replace('#',''));return{reference:state.activeHex,closest:closest(3).map(p=>p.shade)}}})}
setReference(state.activeHex);renderProducts();renderCompare();state.tryProduct=products[0];buildTryOn(products[0]);updateModalProductReference('try',products[0]);renderTrySuggestions(products[0]);seedSkin(products[0]);renderScanMatches();registerTools();
